        for c in range(6, w)
        if grid[r][c] != 0
    ]

    best_period = 2
    best_errors = None
    best_map = {}

    for period in range(2, 11):
        buckets = [{} for _ in range(period)]
        for r, c, value in samples:
            residue = (r + c) % period
            buckets[residue][value] = buckets[residue].get(value, 0) + 1

        errors = sum(
            sum(counts.values()) - max(counts.values())
            for counts in buckets if counts
        )
        if best_errors is None or errors < best_errors:
            best_errors = errors
            best_period = period
            best_map = {
                i: max(counts, key=counts.get)
                for i, counts in enumerate(buckets) if counts
            }

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                residue = (r + c) % best_period
                if residue in best_map:
                    out[r][c] = best_map[residue]

    return out
